<section class="admin-v2-page-intro"><div><span class="admin-v2-eyebrow">WRITER MEMBERSHIP</span><h2>طلبات انتساب الكتّاب</h2><p>كل طلب مرتبط بالحساب الذي أنشأه صاحبه. الموافقة لا تنشئ حسابًا جديدًا ولا تغيّر كلمة المرور.</p></div><form class="admin-v2-filter" method="get"><input name="q" value="<?=e($q)?>" placeholder="اسم أو بريد أو اسم مستخدم"><select name="status"><option value="">كل الحالات</option><?php foreach(['pending'=>'معلق','under_review'=>'قيد المراجعة','changes_requested'=>'تعديلات مطلوبة','approved'=>'مقبول','rejected'=>'مرفوض','suspended'=>'موقوف'] as $key=>$label):?><option value="<?=e($key)?>" <?=$status===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select><button class="admin-v2-button primary" type="submit">تصفية</button></form></section>
<section class="admin-v2-table-panel"><div class="admin-v2-table-wrap"><table class="admin-v2-table"><thead><tr><th>المتقدم</th><th>الحساب</th><th>الحالة</th><th>آخر دخول</th><th>إجراء</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5"><div class="admin-v2-empty">لا توجد طلبات مطابقة.</div></td></tr><?php else: foreach($rows as $row):?><tr><td><strong><?=e((string)$row['name'])?></strong><small><?=e((string)($row['email']??''))?></small></td><td><code><?=e((string)($row['username']??'—'))?></code><small><?=e((string)($row['user_status']??'—'))?></small></td><td><span class="admin-v2-badge <?=e((string)$row['status'])?>"><?=e((string)$row['status'])?></span></td><td><?=e((string)($row['last_login_at']??'—'))?></td><td><details class="admin-v2-actions"><summary>إدارة</summary><form method="post" action="/admin-v2/applications/action"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($row['id'])?>"><label>سبب/ملاحظة<textarea name="reason" rows="2"></textarea></label><div class="admin-v2-action-grid"><button name="action" value="review" type="submit">قيد المراجعة</button><button name="action" value="request_changes" type="submit">طلب تعديلات</button><button name="action" value="approve" type="submit" class="good">موافقة</button><button name="action" value="reject" type="submit" class="danger">رفض</button><button name="action" value="message" type="submit">رسالة داخلية</button></div><label class="admin-v2-message-field">رسالة داخل الحساب<textarea name="message" rows="2"></textarea></label></form></details></td></tr><?php endforeach; endif;?></tbody></table></div></section>
